import { render, screen, fireEvent } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';
import { TournamentForm } from './TournamentForm';
import { Tournament } from '../models/Tournament';

describe('TournamentForm', () => {
  const mockTournament = new Tournament({
    id: 'test-id',
    name: 'Test Tournament',
    password: 'password',
    questionsPerParticipant: 5,
    points: '10,20,30,40,50',
    regulation: 'Test Regulation',
    status: 'pending',
    createdAt: new Date(),
    updatedAt: new Date(),
  });

  it('新規作成モードで正しくレンダリングされること', () => {
    const { container } = render(<TournamentForm onSubmit={vi.fn()} isEditMode={false} />);

    expect(screen.getByRole('textbox', { name: '大会名' })).toHaveValue('');
    expect(container.querySelector('input[type="password"]')).toBeInTheDocument();
    expect(screen.getByText('この内容で大会を作成する')).toBeInTheDocument();
  });

  it('編集モードで初期値がフォームに設定されること', () => {
    render(<TournamentForm tournament={mockTournament} onSubmit={vi.fn()} isEditMode={true} />);

    expect(screen.getByRole('textbox', { name: '大会名' })).toHaveValue('Test Tournament');
    expect(screen.getByRole('spinbutton', { name: '参加者1人あたりの問題作成数' })).toHaveValue(5);
    expect(screen.getByRole('textbox', { name: '各問題の配点 (カンマ区切り)' })).toHaveValue('10,20,30,40,50');
    expect(screen.getByRole('textbox', { name: 'レギュレーション' })).toHaveValue('Test Regulation');
    expect(screen.getByText('この内容で更新する')).toBeInTheDocument();
  });

  it('フォームをサブミットすると、入力データでonSubmitが呼び出されること', () => {
    const handleSubmit = vi.fn();
    const { container } = render(<TournamentForm onSubmit={handleSubmit} isEditMode={false} />);

    fireEvent.change(screen.getByRole('textbox', { name: '大会名' }), { target: { value: 'New Tournament' } });
    const passwordInput = container.querySelector('input[type="password"]');
    expect(passwordInput).not.toBeNull();
    if (passwordInput) {
      fireEvent.change(passwordInput, { target: { value: 'new_password' } });
    }

    fireEvent.click(screen.getByText('この内容で大会を作成する'));

    expect(handleSubmit).toHaveBeenCalledWith(
      expect.objectContaining({
        name: 'New Tournament',
        password: 'new_password',
      })
    );
  });
});

import { Participant } from './Participant';

/**
 * 大会情報を表現するクラス
 */
export class Tournament {
  /**
   * 大会ID
   * @type {string}
   */
  id: string;

  /**
   * 大会名
   * @type {string}
   */
  name: string;

  /**
   * 参加者1人あたりの問題作成数
   * @type {number}
   */
  questionsPerParticipant: number;

  /**
   * 各問題の配点（カンマ区切り）
   * @type {string}
   */
  points: string;

  /**
   * 大会のレギュレーション
   * @type {(string | null)}
   */
  regulation?: string | null;

  /**
   * 大会の状態
   * @type {string}
   */
  status: string;

  /**
   * 大会に参加している参加者のリスト
   * @type {Participant[]}
   */
  participants: Participant[];

  constructor(data: {
    id: string;
    name: string;
    questionsPerParticipant: number;
    points: string;
    regulation?: string | null;
    status: string;
    participants: Participant[];
  }) {
    this.id = data.id;
    this.name = data.name;
    this.questionsPerParticipant = data.questionsPerParticipant;
    this.points = data.points;
    this.regulation = data.regulation;
    this.status = data.status;
    this.participants = data.participants;
  }

  /**
   * APIから取得したデータを元にTournamentインスタンスを生成します。
   * @param {unknown} data - APIから取得したデータ
   * @returns {Tournament} Tournamentインスタンス
   * @throws {Error} APIのデータ形式が不正な場合にエラーをスローします。
   */
  public static fromApi(data: unknown): Tournament {
    if (
      typeof data === 'object' &&
      data !== null &&
      'id' in data &&
      typeof data.id === 'string' &&
      'name' in data &&
      typeof data.name === 'string' &&
      'questionsPerParticipant' in data &&
      typeof data.questionsPerParticipant === 'number' &&
      'points' in data &&
      typeof data.points === 'string' &&
      'status' in data &&
      typeof data.status === 'string' &&
      ('participants' in data ? Array.isArray(data.participants) : true) // participants is optional
    ) {
      const tournamentData = {
        id: data.id,
        name: data.name,
        questionsPerParticipant: data.questionsPerParticipant,
        points: data.points,
        regulation: 'regulation' in data ? (data.regulation as string) : null,
        status: data.status,
        participants: 'participants' in data ? (data.participants as unknown[]).map(Participant.fromApi) : [],
      };
      return new Tournament(tournamentData);
    }
    throw new Error('Invalid tournament data format from API');
  }
}

