          <TextField
            label="各問題の配点 (カンマ区切り)"
            fullWidth
            required
            value={points}
            onChange={(e) => setPoints(e.target.value)}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            label="レギュレーション"
            multiline
            rows={4}
            fullWidth
            value={regulation}
            onChange={(e) => setRegulation(e.target.value)}
          />
