import { useState } from 'react';
import {
  Button,
  Container,
  Typography,
  Box,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  TextField,
} from '@mui/material';
import { styled } from '@mui/material/styles';
import { Link, useParams, useNavigate } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import { pathToTournamentRegisterParticipant, pathToOrganizerDashboard } from '../helpers/route-helpers';
import { tournamentApiClient } from '../api/TournamentApiClient';

const StyledContainer = styled(Container)(({ theme }) => ({
  textAlign: 'center',
  marginTop: theme.spacing(8),
}));

const TournamentPortalPage = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);
  const [password, setPassword] = useState('');

  const { data: tournament } = useQuery({
    queryKey: ['tournament', id],
    queryFn: () => {
      if (!id) {
        throw new Error('Tournament ID is not defined');
      }
      return tournamentApiClient.get(id);
    },
    enabled: !!id,
  });

  const handleClickOpen = () => {
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
    setPassword('');
  };

  const handleLogin = async () => {
    if (!id) return;
    try {
      await tournamentApiClient.login(id, password);
      handleClose();
      setTimeout(() => {
        navigate(pathToOrganizerDashboard(id));
      }, 0);
    } catch (error) {
      console.error(error);
      alert('パスワードが違います。');
      setPassword('');
    }
  };

  return (
    <StyledContainer maxWidth="md">
      <Typography variant="h4" component="h1" gutterBottom>
        {tournament ? `大会: ${tournament.name}` : '大会ポータル'}
      </Typography>
      <Typography variant="h6" color="textSecondary" paragraph>
        参加方法を選択してください
      </Typography>
      <Box sx={{ mt: 4, display: 'flex', justifyContent: 'center', gap: 2 }}>
        <Button variant="outlined" color="primary" size="large" onClick={handleClickOpen}>
          主催者としてログイン
        </Button>
        <Button
          component={Link}
          to={pathToTournamentRegisterParticipant(id || '')}
          variant="contained"
          color="primary"
          size="large"
        >
          参加者として新規登録
        </Button>
      </Box>

      <Dialog open={open} onClose={handleClose}>
