  id: 'test-id',
  name: 'Test Tournament',
  questionsPerParticipant: 1,
  points: '10',
  regulation: '',
  status: 'in_progress',
  participants: [
    new Participant({
      id: 'p-1',
      name: 'Participant 1',
      tournamentId: 'test-id',
      created: 1,
      required: 1,
      quizzes: [
        new Quiz({
