function handler(event) {
  var request = event.request;
  var headers = request.headers;

  // Basic認証のユーザー名とパスワードをCloudFormationのパラメータから受け取る
  // この値はCloudFront Functionの関連付け時に環境変数のように設定される
  var authUser = "{{resolve:ssm:BASIC_AUTH_USER:1}}";
  var authPass = "{{resolve:ssm:BASIC_AUTH_PASS:1}}";

  var authString = "Basic " + (authUser + ":" + authPass).toString("base64");

  if (
    typeof headers.authorization === "undefined" ||
    headers.authorization.value !== authString
  ) {
    return {
      statusCode: 401,
      statusDescription: "Unauthorized",
      headers: {
        "www-authenticate": { value: 'Basic realm="Enter credentials"' },
      },
    };
  }

  return request;
}

